<?php $cursorQuery = '&uidvalidity=' . (int)($uidValidity ?? 0); if(($cursorBefore??null)!==null) $cursorQuery .= '&before=' . (int)$cursorBefore; elseif(($cursorAfter??null)!==null) $cursorQuery .= '&after=' . (int)$cursorAfter; ?>
<div class="heading"><div><h1>Webmail</h1><p>Read and send messages through your configured mail server.</p></div><a class="button secondary" href="/dashboard">Dashboard</a></div>
<?php if($error): ?><p class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endif; ?>
<?php if(isset($_GET['sent'])): ?><p class="notice">The SMTP server accepted the message for delivery.<?php if(($_GET['sent_copy']??'')==='saved'): ?> A copy was saved to Sent.<?php elseif(($_GET['sent_copy']??'')==='failed'): ?> The Sent copy could not be saved; the message was still accepted by SMTP.<?php elseif(($_GET['sent_copy']??'')==='pending'): ?> The Sent-copy step did not finish. Check Sent before taking any further action; do not resend this message.<?php else: ?> No Sent folder was available, so no server-side copy was saved.<?php endif; ?></p><?php endif; ?>
<?php if(isset($_GET['moved'])): ?><p class="notice">Message moved.</p><?php endif; ?><?php if(isset($_GET['draft'])): ?><p class="notice">Draft saved to the IMAP server.</p><?php endif; ?><?php if(isset($_GET['flagged'])): ?><p class="notice">Message flags updated.</p><?php endif; ?>
<?php if(!$mailboxes): ?><section class="panel"><p>No active mailbox is assigned to your account.</p></section><?php else: ?>
<section class="panel">
<form method="get" action="/mail" class="toolbar"><label>Mailbox<select name="mailbox" data-auto-submit><?php foreach($mailboxes as $m): ?><option value="<?= (int)$m['id'] ?>" <?= (int)($activeMailbox['id']??($_GET['mailbox']??0))===(int)$m['id']?'selected':'' ?>><?= htmlspecialchars($m['email'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><label>Search<input name="q" value="<?= htmlspecialchars($query, ENT_QUOTES, 'UTF-8') ?>" maxlength="200" placeholder="Search this folder"></label><button type="submit">Search</button></form>
<?php if($activeMailbox): ?>
<div class="mail-layout">
<aside class="folder-list"><h2>Folders</h2><?php foreach($folders as $folder): ?><a class="<?= $folder['name']===$selectedFolder?'active':'' ?>" href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($folder['name']) ?>"><?= htmlspecialchars($folder['name'], ENT_QUOTES, 'UTF-8') ?></a><?php endforeach; ?></aside>
<section class="message-column" data-webmail-sync data-mailbox-id="<?= (int)$activeMailbox['id'] ?>" data-folder="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>" data-uid-validity="<?= (int)($uidValidity??0) ?>" data-latest-uid="<?= (int)($latestUid??0) ?>" data-query="<?= htmlspecialchars($query??'', ENT_QUOTES, 'UTF-8') ?>"><h2><?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?></h2><p class="notice" data-sync-notice hidden></p><script src="/assets/webmail-sync.js" defer></script><script src="/assets/webmail-compose.js" defer></script>
<?php if(!$messages): ?><p class="muted">This folder is empty.</p><?php else: ?><div class="message-list"><?php foreach($messages as $message): ?><a class="message-row <?= $message['seen']?'':'unread' ?>" href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$message['uid'] ?>&page=<?= (int)$page ?>&q=<?= rawurlencode($query) ?><?= $cursorQuery ?>"><span><?= htmlspecialchars($message['from'], ENT_QUOTES, 'UTF-8') ?></span><strong><?= !empty($message['flagged']) ? '★ ' : '' ?><?= htmlspecialchars($message['subject'], ENT_QUOTES, 'UTF-8') ?><?php if(($message['thread_count']??1)>1): ?> <small>(<?= (int)$message['thread_count'] ?> on this page)</small><?php endif; ?></strong><time><?= htmlspecialchars($message['date'], ENT_QUOTES, 'UTF-8') ?></time></a><?php endforeach; ?></div><?php endif; ?>
<?php if($messages): ?><nav class="mail-pagination">
<?php if(($cursorBefore??null)!==null || (($cursorAfter??null)!==null && $hasMore)): ?><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&after=<?= (int)($messages[0]['uid']??0) ?>&uidvalidity=<?= (int)$uidValidity ?>&q=<?= rawurlencode($query) ?>">Newer messages</a><?php endif; ?>
<?php if(($cursorAfter??null)!==null || $hasMore): ?><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&before=<?= (int)($oldestUid ?? ($messages[count($messages)-1]['uid']??0)) ?>&uidvalidity=<?= (int)$uidValidity ?>&q=<?= rawurlencode($query) ?>">Older messages</a><?php endif; ?>
</nav><?php endif; ?>
<?php if($selectedMessage): ?><article class="panel message-detail"><h2><?= htmlspecialchars($selectedMessage['subject'], ENT_QUOTES, 'UTF-8') ?></h2><p><strong>From:</strong> <?= htmlspecialchars($selectedMessage['from'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>To:</strong> <?= htmlspecialchars($selectedMessage['to'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>Date:</strong> <?= htmlspecialchars($selectedMessage['date'], ENT_QUOTES, 'UTF-8') ?></p><?php if(count($relatedMessages??[])>1): ?><section class="conversation-list"><h3>Conversation messages</h3><ul><?php foreach($relatedMessages as $related): ?><li><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$related['uid'] ?>&page=<?= (int)$page ?>&q=<?= rawurlencode($query) ?><?= $cursorQuery ?>"><?= htmlspecialchars($related['from'], ENT_QUOTES, 'UTF-8') ?> — <?= htmlspecialchars($related['subject'], ENT_QUOTES, 'UTF-8') ?> — <?= htmlspecialchars($related['date'], ENT_QUOTES, 'UTF-8') ?></a></li><?php endforeach; ?></ul></section><?php endif; ?><p class="message-actions"><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$selectedMessage['uid'] ?>&page=<?= (int)$page ?>&q=<?= rawurlencode($query) ?><?= $cursorQuery ?>&compose=reply">Reply</a><a href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$selectedMessage['uid'] ?>&page=<?= (int)$page ?>&q=<?= rawurlencode($query) ?><?= $cursorQuery ?>&compose=forward">Forward</a></p><pre><?= htmlspecialchars($selectedMessage['body'], ENT_QUOTES, 'UTF-8') ?></pre><div class="message-actions"><form method="post" action="/mail/flag"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="uid" value="<?= (int)$selectedMessage['uid'] ?>"><input type="hidden" name="uidvalidity" value="<?= (int)($uidValidity??0) ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="flag" value="Flagged"><input type="hidden" name="enabled" value="<?= !empty($selectedMessage['flagged']) ? '0' : '1' ?>"><button class="secondary small"><?= !empty($selectedMessage['flagged']) ? 'Remove star' : 'Star message' ?></button></form><form method="post" action="/mail/flag"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="uid" value="<?= (int)$selectedMessage['uid'] ?>"><input type="hidden" name="uidvalidity" value="<?= (int)($uidValidity??0) ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="flag" value="Seen"><input type="hidden" name="enabled" value="0"><button class="secondary small">Mark unread</button></form></div><?php if(!empty($selectedMessage['attachments'])): ?><section class="attachments"><h3>Attachments</h3><ul><?php foreach($selectedMessage['attachments'] as $attachment): ?><li><a href="/mail/attachment?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$selectedMessage['uid'] ?>&uidvalidity=<?= (int)($uidValidity??0) ?>&section=<?= rawurlencode($attachment['section']) ?>"><?= htmlspecialchars($attachment['filename'], ENT_QUOTES, 'UTF-8') ?></a> <small><?= number_format(((int)$attachment['size'])/1024, 1) ?> KB</small></li><?php endforeach; ?></ul></section><?php endif; ?><?php $folderNames = array_column($folders, 'name'); $trash = in_array('Trash', $folderNames, true) ? 'Trash' : (in_array('Deleted Items', $folderNames, true) ? 'Deleted Items' : ''); $spam = in_array('Spam', $folderNames, true) ? 'Spam' : (in_array('Junk', $folderNames, true) ? 'Junk' : ''); ?>
<?php foreach (['Trash' => $trash, 'Spam' => $spam] as $label => $destination): ?><?php if($destination): ?><form method="post" action="/mail/move" class="inline"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="uid" value="<?= (int)$selectedMessage['uid'] ?>"><input type="hidden" name="uidvalidity" value="<?= (int)($uidValidity??0) ?>"><input type="hidden" name="source" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="destination" value="<?= htmlspecialchars($destination, ENT_QUOTES, 'UTF-8') ?>"><button class="<?= $label==='Trash'?'danger':'secondary' ?> small">Move to <?= $label ?></button></form><?php endif; ?><?php endforeach; ?></article><?php endif; ?>
</section></div>
<?php else: ?><p class="muted">Select an active mailbox to continue.</p><?php endif; ?></section>
<?php if($activeMailbox): ?><section class="panel compose"><h2>Compose</h2><form method="post" action="/mail/send" enctype="multipart/form-data"><input type="hidden" name="submission_id" value="<?= htmlspecialchars($compose['submission_id']??'', ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="q" value="<?= htmlspecialchars($query, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="in_reply_to" value="<?= htmlspecialchars($compose['in_reply_to'], ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="references" value="<?= htmlspecialchars($compose['references'], ENT_QUOTES, 'UTF-8') ?>"><label>From<input readonly value="<?= htmlspecialchars($activeMailbox['email'], ENT_QUOTES, 'UTF-8') ?>"></label><label>To<input name="to" value="<?= htmlspecialchars($compose['to'], ENT_QUOTES, 'UTF-8') ?>" placeholder="recipient@example.com (separate multiple recipients with commas)"></label><label>Cc<input name="cc" value="<?= htmlspecialchars($compose['cc']??'', ENT_QUOTES, 'UTF-8') ?>" placeholder="Optional carbon-copy recipients"></label><label>Bcc<input name="bcc" value="<?= htmlspecialchars($compose['bcc']??'', ENT_QUOTES, 'UTF-8') ?>" placeholder="Optional blind-copy recipients"></label><label>Reply-To<input type="email" name="reply_to" value="<?= htmlspecialchars($compose['reply_to']??'', ENT_QUOTES, 'UTF-8') ?>" placeholder="Optional reply address"></label><label>Subject<input name="subject" value="<?= htmlspecialchars($compose['subject'], ENT_QUOTES, 'UTF-8') ?>" maxlength="998"></label><label>Plain-text message<textarea name="body" rows="8" placeholder="Plain-text version"><?= htmlspecialchars($compose['body'], ENT_QUOTES, 'UTF-8') ?></textarea></label><div class="rich-compose"><label>Rich-text HTML alternative</label><div class="rich-toolbar" role="toolbar" aria-label="Text formatting"><button type="button" class="secondary small" data-rich-command="bold" aria-label="Bold"><strong>B</strong></button><button type="button" class="secondary small" data-rich-command="italic" aria-label="Italic"><em>I</em></button><button type="button" class="secondary small" data-rich-command="underline" aria-label="Underline"><u>U</u></button><button type="button" class="secondary small" data-rich-command="insertUnorderedList">• List</button><button type="button" class="secondary small" data-rich-command="insertOrderedList">1. List</button><button type="button" class="secondary small" data-rich-link>Link</button></div><div class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Rich-text HTML message" data-rich-editor data-placeholder="Optional formatted message"><?= $compose['html_body']??'' ?></div><textarea name="html_body" class="rich-source" data-rich-source hidden><?= htmlspecialchars($compose['html_body']??'', ENT_QUOTES, 'UTF-8') ?></textarea></div><label>Attachments<input type="file" name="attachments[]" multiple><small>Up to 10 files; 25 MB total</small></label><button type="submit">Send message</button> <button type="submit" class="secondary" formaction="/mail/draft">Save draft</button></form></section><?php endif; ?>
<?php endif; ?>
